"question": "If \\(\\left(r+\\dfrac1r\\right)^2=3,\\) then \\(r^3+\\dfrac1{r^3}\\) equals",
"questionType": "text",
"choices": {
"A": "\\(1\\)",
"B": "\\(2\\)",
"C": "\\(0\\)",
"D": "\\(3\\)",
"E": "\\(6\\)"
},
