"responseType": "choice",
"question": "The logarithm of \\(0.0625\\) to the base \\(2\\) is:",
"questionType": "text",
"choices": {
"A": "\\(0.025\\)",
"B": "\\(0.25\\)",
"C": "\\(5\\)",
"D": "\\(-4\\)",
"E": "\\(-2\\)"
},
