"responseType": "choice",
"question": "Define an operation \\(*\\) for positive real numbers by \\(a*b=\\dfrac{ab}{a+b}.\\) Then \\(4*(4*4)\\) equals:",
"questionType": "text",
"choices": {
"A": "\\(\\dfrac34\\)",
"B": "\\(1\\)",
"C": "\\(\\dfrac43\\)",
"D": "\\(2\\)",
"E": "\\(\\dfrac{16}{3}\\)"
},
"choiceOrder": [
"A",
"B",
"C",
"D",
"E"
],
"choicesType": "text",
