"responseType": "choice",
"question": "If the line \\(y=mx+1\\) intersects the ellipse \\(x^2+4y^2=1\\) exactly once, then the value of \\(m^2\\) is:",
"questionType": "text",
"choices": {
"A": "\\(\\frac{1}{2}\\)",
"B": "\\(\\frac{2}{3}\\)",
"C": "\\(\\frac{3}{4}\\)",
"D": "\\(\\frac{4}{5}\\)",
"E": "\\(\\frac{5}{6}\\)"
},
"choiceOrder": [
"A",
"B",
"C",
"D",
"E"
],
"choicesType": "text",
"answer": "C",
