"question": "If \\(3(4x+5\\pi)=P,\\) then \\(6(8x+10\\pi)=\\)",
"questionType": "text",
"choices": {
"A": "\\(2P\\)",
"B": "\\(4P\\)",
"C": "\\(6P\\)",
"D": "\\(8P\\)",
"E": "\\(18P\\)"
},
